function addChat(role,text){const div=document.createElement('div');div.className='msg '+role;div.innerHTML=`<b>${role==='jarvis'?'JARVIS':'YOU'}</b><p>${esc(text)}</p>`;$('chatLog').appendChild(div);$('chatLog').scrollTop=$('chatLog').scrollHeight}
function findProject(text){const n=text.replace(/\s/g,'').toLowerCase();return DATA.projects.find(p=>n.includes(p.name.replace(/\s/g,'').toLowerCase()))}function numberFrom(text){const m=text.match(/(\d+(?:\.\d+)?)/);return m?Number(m[1]):null}function speak(text){try{if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ja-JP';speechSynthesis.speak(u)}}catch{}}
function execute(raw){const text=(raw||'').trim();if(!text)return;$('voiceText').value='';addChat('user',text);const t=text.replace(/\s/g,''),p=findProject(text),n=numberFrom(text);let r='';if(/配送|シフト/.test(t)&&/開|見|管理/.test(t)){go('shiftboard');r='シフト・配送の統合画面を開きました。'}else if(/ドライバー|稼働日数|何日/.test(t)&&/開|見/.test(t)){go('shiftboard');r='シフト画面を開きました。'}else if(/売上|利益|粗利/.test(t)&&/開|画面/.test(t)){go('sales');r='売上・利益画面を開きました。'}else if(/不足/.test(t)){const xs=DATA.projects.filter(x=>+x.active<+x.required);r=xs.length?`不足は${xs.length}案件。${xs.map(x=>`${x.name} ${+x.required-+x.active}台`).join('、')}です。`:'不足案件はありません。'}else if(/売上/.test(t)){const s=DATA.projects.reduce((z,x)=>z+(DATA.month_actuals[x.name]||0)*(+x.unit_price||0),0);r=`8月累計売上は${Math.round(s).toLocaleString()}円です。`}else if(/粗利|利益/.test(t)){const tax=1+(DATA.sales_tax_rate||0),g=DATA.projects.reduce((z,x)=>{const a=DATA.month_actuals[x.name]||0;return z+a*(+x.unit_price||0)*tax-a*(+x.driver_pay||0)},0);r=`8月粗利は${Math.round(g).toLocaleString()}円です。`}else if(/誰.*出勤|出勤.*誰/.test(t)){const area=Object.keys(AREA_PROJECTS).find(a=>t.includes(a));if(area){const xs=areaToday(area);r=xs.length?`${area}の活動報告上の出勤は、${xs.map(x=>x.driver+(x.project?'（'+x.project+'）':'')).join('、')}です。`:`${area}は今日の活動報告がまだ未入力です。` }else r='エリア名も一緒に言ってください。例：静岡は今日誰が出勤？'}else if(/何日|稼働日数/.test(t)){const d=DRIVERS.find(x=>t.includes(x.name.replace(/\s/g,''))||t.includes(x.name.split(' ')[0]));r=d?`${d.name}の今月稼働は現在${driverMonthDays(d)}日です。`:'ドライバー名を一緒に入力してください。'}else if(p&&n!=null&&/(稼働|台にして|台へ)/.test(t)){p.active=Math.max(0,n);render();r=`${p.name}の稼働を${n}台に変更しました。`}else if(/今日.*活動報告|活動報告.*今日|今日の活動報告/.test(t)){const xs=attendanceFor();r=xs.length?`今日の活動報告は${xs.length}件です。${Object.keys(AREA_PROJECTS).map(a=>{const z=xs.filter(x=>x.area===a&&x.status==='出勤');return z.length?`${a}：${z.map(x=>x.driver).join('、')}`:''}).filter(Boolean).join('。')}`:'今日の活動報告はまだ登録されていません。';}else if(/シフト表/.test(t)){go('shiftboard');r='シフト表を開きました。'}else if(/配送管理表|Excel/.test(t)&&/開|見|確認/.test(t)){go('workbook');r='配送管理表Excelを開きました。'}else if(/活動報告/.test(t)&&/開|入力/.test(t)){go('shiftboard');setTimeout(()=>$('attDriver')?.focus(),100);r='シフト画面の活動報告入力を開きました。'}else if(/保存/.test(t)){localStorage.setItem(STORAGE_KEY,JSON.stringify(DATA));localStorage.setItem(ATT_KEY,JSON.stringify(ATT));r='保存しました。'}else{r='現在のJARVISではJARVIS内の業務データ・画面操作には回答できます。一般的な質問にも何でも答える機能は、秘密鍵をブラウザに置かない安全なAIバックエンド接続を追加すると完成します。'}addChat('jarvis',r);speak(r)}
$('voiceSend')?.addEventListener('click',()=>execute($('voiceText').value));$('voiceText')?.addEventListener('keydown',e=>{if(e.key==='Enter')execute($('voiceText').value)});document.querySelectorAll('[data-voicecmd]').forEach(b=>b.addEventListener('click',()=>execute(b.dataset.voicecmd)));const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){const rec=new SR();rec.lang='ja-JP';rec.interimResults=false;rec.onstart=()=>{$('voiceBtn').classList.add('listening');$('voiceStatus').textContent='JARVIS LISTENING...'};rec.onend=()=>{$('voiceBtn').classList.remove('listening');$('voiceStatus').textContent='マイクを押して話せます。'};rec.onresult=e=>execute(e.results[0][0].transcript);rec.onerror=()=>addChat('jarvis','音声認識を開始できませんでした。マイク許可を確認してください。');$('voiceBtn')?.addEventListener('click',()=>{try{rec.start()}catch{}})}else $('voiceBtn')?.addEventListener('click',()=>addChat('jarvis','このブラウザは音声認識非対応です。テキスト入力は使えます。'));

// ===== V4.6 SHIFT MATRIX =====
function daysInMonth(ym){const [y,m]=ym.split('-').map(Number);return new Date(y,m,0).getDate()}
function shiftAreaDrivers(area){return DRIVERS.filter(d=>area==='all'||driverAreas(d).includes(area))}
function getShiftRec(date,d){return ATT.find(a=>a.date===date&&normName(a.driver)===normName(d.name))}
function cycleShift(date,d){
  const states=['出勤','休み','欠車',''];
  let rec=getShiftRec(date,d),cur=rec?.status||'',next=states[(states.indexOf(cur)+1)%states.length];
  if(!next){ATT=ATT.filter(a=>!(a.date===date&&normName(a.driver)===normName(d.name)));}
  else{
    const area=rec?.area||d.area,project=rec?.project||AREA_PROJECTS[area]?.[0]||'';
    const nr={date,area,driver:d.name,project,status:next,work:rec?.work||''};
    const idx=ATT.findIndex(a=>a.date===date&&normName(a.driver)===normName(d.name));
    if(idx>=0)ATT[idx]=nr; else ATT.push(nr);
  }
  localStorage.setItem(ATT_KEY,JSON.stringify(ATT));renderShiftMatrix();renderDrivers();renderAreaDrivers();
}
function editShiftCell(date,d){
  const old=getShiftRec(date,d);const cur=(old?.work&&!['〇','○'].includes(old.work))?old.work:(old?.status==='休み'?'休':old?.status==='欠車'?'×':old?.status==='研修'?'研修':old?.status==='出勤'?'○':'');
  const v=prompt(`${d.name} / ${date}\n入力: ○ / 休 / × / AM / MX / CX / お酒 / 営業 / 下田 / R / 空欄で削除`,cur);
  if(v===null)return;const x=v.trim();
  if(!x){ATT=ATT.filter(a=>!(a.date===date&&normName(a.driver)===normName(d.name)));}
  else{let status='出勤',work=x;if(x==='休'||x==='休み'){status='休み';work='休'}else if(x==='×'||x==='欠車'){status='欠車';work='×'}else if(x==='研修'){status='研修';work='研修'}else if(x==='○'||x==='〇'){status='出勤';work='○'}
    const area=old?.area||d.area,project=old?.project||AREA_PROJECTS[area]?.[0]||'';const nr={date,area,driver:d.name,project,status,work,source:'manual-v492'};const i=ATT.findIndex(a=>a.date===date&&normName(a.driver)===normName(d.name));if(i>=0)ATT[i]=nr;else ATT.push(nr)}
  localStorage.setItem(ATT_KEY,JSON.stringify(ATT));renderShiftMatrix();renderAreaDrivers();render();
}
function renderShiftMatrix(){
  if(!$('shiftMatrix'))return;
  const ym=$('shiftMonth')?.value||'2026-08',area=$('shiftArea')?.value||'all',n=daysInMonth(ym),drivers=shiftAreaDrivers(area);
  let html='<div class="shift-row shift-head"><div class="sticky-name">ドライバー</div>';
  for(let day=1;day<=n;day++){const [y,m]=ym.split('-').map(Number),w=['日','月','火','水','木','金','土'][new Date(y,m-1,day).getDay()],wc=w==='日'?' sun':w==='土'?' sat':'';html+=`<div class="shift-date${wc}"><span>${day}</span><small>(${w})</small></div>`;}
  html+='</div>';
  drivers.forEach(d=>{
    html+=`<div class="shift-row"><div class="sticky-name"><b>${esc(d.name)}</b><small>${driverAreas(d).join(' / ')}</small></div>`;
    for(let day=1;day<=n;day++){
      const date=`${ym}-${String(day).padStart(2,'0')}`,r=getShiftRec(date,d),s=r?.status||'';
      const cls=s==='出勤'?'shift-on':s==='休み'?'shift-off':s==='欠車'?'shift-bad':'';
      const label=s==='休み'?'休':s==='欠車'?'×':s==='研修'?(r?.work||'研'):(s==='出勤'?((r?.work&& !['〇','○'].includes(r.work))?r.work:'○'):'・');html+=`<button type="button" class="shift-cell ${cls}" title="${esc(r?.work||s)}" data-date="${date}" data-driver="${esc(d.name)}" data-area="${d.area}">${esc(label)}</button>`;
    }
    html+='</div>';
  });
  $('shiftMatrix').innerHTML=html;
  document.querySelectorAll('.shift-cell').forEach(b=>b.addEventListener('click',()=>{const d=DRIVERS.find(x=>normName(x.name)===normName(b.dataset.driver));if(!d)return;if(!SHIFT_EDIT){cycleShift(b.dataset.date,d);return}editShiftCell(b.dataset.date,d)}));
}
function initShiftControls(){
 if(!$('shiftArea'))return;
 $('shiftArea').innerHTML='<option value="all">全エリア</option>'+Object.keys(AREA_PROJECTS).map(a=>`<option>${a}</option>`).join('');
 $('shiftEditBtn')?.addEventListener('click',()=>{SHIFT_EDIT=!SHIFT_EDIT;$('shiftEditBtn').textContent=SHIFT_EDIT?'✓ シフト直接編集 OFF':'✎ シフト直接編集 ON';$('attendanceStatus').textContent=SHIFT_EDIT?'編集ON：セルをタップして ○ / 休 / × / AM / MX / CX / お酒 などを直接入力できます。':'編集OFF：セルタップは簡易切替です。';renderShiftMatrix()});
 $('shiftArea').addEventListener('change',renderShiftMatrix);$('shiftMonth').addEventListener('change',renderShiftMatrix);
 $('shiftSaveBtn').addEventListener('click',()=>{localStorage.setItem(ATT_KEY,JSON.stringify(ATT));$('attendanceStatus')&&($('attendanceStatus').textContent='✓ シフトを保存しました。出勤状況・配送情報にも反映済みです');render();renderAreaDrivers()});
 $('shiftExportBtn').addEventListener('click',()=>{
   const ym=$('shiftMonth').value,area=$('shiftArea').value,ds=shiftAreaDrivers(area),n=daysInMonth(ym);
   const rows=[['ドライバー','エリア',...Array.from({length:n},(_,i)=>i+1)]];
   ds.forEach(d=>rows.push([d.name,d.area,...Array.from({length:n},(_,i)=>{const date=`${ym}-${String(i+1).padStart(2,'0')}`,r=getShiftRec(date,d);return r?.status||''})]));
   const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');
   const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`JARVIS_シフト_${ym}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
 });
}

// ===== V4.6 XLSX WORKSPACE / IndexedDB =====
let WB=null,WB_EDIT=false,WB_NAME='JARVIS_配送管理表.xlsx',WB_SELECTED_COL=null;
let SHIFT_EDIT=false;
function idb(){return new Promise((resolve,reject)=>{const r=indexedDB.open('jarvis-v47-db',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveWorkbookBytes(bytes,name){const db=await idb();return new Promise((res,rej)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({bytes:Array.from(new Uint8Array(bytes)),name,ts:Date.now()},'deliveryWorkbookV478');tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function loadWorkbookBytes(){const db=await idb();return new Promise((res,rej)=>{const tx=db.transaction('files','readonly');const q=tx.objectStore('files').get('deliveryWorkbookV478');q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}
function workbookAOA(){if(!WB)return [];const s=$('sheetSelect').value;return XLSX.utils.sheet_to_json(WB.Sheets[s],{header:1,defval:''})}
function renderWorkbook(){
 if(!$('workbookTable'))return;
 if(!WB){$('workbookTable').innerHTML='<tbody><tr><td>Excelファイルを読み込んでください。</td></tr></tbody>';return}
 const name=$('sheetSelect').value||WB.SheetNames[0],aoa=XLSX.utils.sheet_to_json(WB.Sheets[name],{header:1,defval:''});
 const maxCols=Math.max(1,...aoa.map(r=>r.length));
 let h='<tbody>';
 aoa.slice(0,300).forEach((row,r)=>{h+='<tr>';for(let c=0;c<maxCols;c++){const v=row[c]??'',sel=WB_SELECTED_COL===c?' selected-col':'';h+=`<td class="${r===2?'workbook-header-cell ':''}${sel}" data-r="${r}" data-c="${c}" ${WB_EDIT?'contenteditable="true"':''}>${esc(v)}</td>`}h+='</tr>'});
 h+='</tbody>';$('workbookTable').innerHTML=h;
 document.querySelectorAll('#workbookTable td').forEach(td=>td.addEventListener('click',()=>{WB_SELECTED_COL=+td.dataset.c;renderWorkbook()}));
 if(WB_EDIT)document.querySelectorAll('#workbookTable td[contenteditable]').forEach(td=>{
   td.addEventListener('click',e=>e.stopPropagation());
   td.addEventListener('focus',()=>{WB_SELECTED_COL=+td.dataset.c});
   td.addEventListener('blur',()=>{const a=workbookAOA();while(a.length<=+td.dataset.r)a.push([]);while(a[+td.dataset.r].length<=+td.dataset.c)a[+td.dataset.r].push('');a[+td.dataset.r][+td.dataset.c]=td.textContent;WB.Sheets[name]=XLSX.utils.aoa_to_sheet(a);});
 });
}
function workbookSheetData(){if(!WB)return null;const name=$('sheetSelect').value||WB.SheetNames[0];return {name,a:XLSX.utils.sheet_to_json(WB.Sheets[name],{header:1,defval:''})}}
function setWorkbookAOA(name,a){WB.Sheets[name]=XLSX.utils.aoa_to_sheet(a);renderWorkbook()}
async function initWorkbook(){
 if(!$('xlsxInput'))return;
 const saved=await loadWorkbookBytes().catch(()=>null);
 if(saved&&window.XLSX){const u8=new Uint8Array(saved.bytes);WB=XLSX.read(u8,{type:'array'});WB_NAME=saved.name||WB_NAME;setupSheetSelect();$('workbookStatus').textContent=`✓ 保存済み配送管理表を読込：${WB_NAME}`;renderWorkbook()}else if(window.XLSX){try{const r=await fetch('./delivery-seed.json?ts='+Date.now(),{cache:'no-store'});if(r.ok){
  const ds=await r.json();WB=XLSX.utils.book_new();
  const order=['静岡','三島Amazon','三島お酒','秋山製麺','三島便','一宮','中村区','野洲','富士','駿河'];
  const names={'静岡':'2026年8月 静岡','三島Amazon':'2026年8月 三島','三島お酒':'2026年8月 三島お酒','秋山製麺':'2026年8月 秋山製麺所','三島便':'2026年8月 三島便','一宮':'2026年8月 一宮','中村区':'2026年8月 中村区','野洲':'2026年8月 野洲','富士':'2026年8月 富士','駿河':'2026年8月 駿河'};
  const biz={'静岡':'静岡12h','三島Amazon':'三島11h','三島お酒':'お酒配送','秋山製麺':'秋山製麺','三島便':'三島5h','一宮':'一宮12h','中村区':'中村12h','野洲':'野洲','富士':'富士','駿河':'駿河'};
  const client={'静岡':'ギオンデリバリー','三島Amazon':'ギオンデリバリー','三島お酒':'お酒配送','秋山製麺':'(有)秋山製麺所','三島便':'三島便','一宮':'ギオンデリバリー','中村区':'ギオンデリバリー','野洲':'遠州トラック','富士':'遠州トラック','駿河':'遠州トラック'};
  const short=n=>String(n||'').trim().split(/[ 　]/)[0];
  order.forEach(project=>{
    const rate=ds.rates[project]||[0,0], rows=ds.rows.filter(x=>x.project===project).sort((a,b)=>a.date.localeCompare(b.date)||a.driver.localeCompare(b.driver,'ja'));
    const a=[];a[0]=['案件名：',project,'','','','請求先：',client[project],'','','','令和8年8月分','','','','','','DR','所属','業務名','単価','実績','合計','調整','支払'];
    a[1]=[];
    a[2]=['走行日','DR','業務名','天引き金額','DR金額','フォロー金額','備考','実績','記入者'];
    // 旧配送管理表と同じ9列。紹介者など備考はJARVIS内で直接編集して保存できる。
    rows.forEach(x=>{const d=new Date(x.date+'T00:00:00');const md=`${d.getMonth()+1}月${d.getDate()}日`;a.push([md,short(x.driver),biz[project]||x.business,0,x.driver_pay,0,x.mark==='〇'?'':x.mark,1,''])});
    const ws=XLSX.utils.aoa_to_sheet(a);ws['!cols']=[{wch:12},{wch:14},{wch:16},{wch:13},{wch:13},{wch:14},{wch:22},{wch:8},{wch:12}];
    XLSX.utils.book_append_sheet(WB,ws,names[project]);
  });
  WB_NAME='2026年8月_配送管理表_既存形式_JARVIS反映.xlsx';setupSheetSelect();$('workbookStatus').textContent='✓ ✓ 旧配送管理表と同じ9列。セル編集→JARVISに保存で手入力を保持します';renderWorkbook()
 }}catch(e){console.warn(e)}}
 $('xlsxInput').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f||!window.XLSX)return;const buf=await f.arrayBuffer();WB=XLSX.read(buf,{type:'array'});WB_NAME=f.name;setupSheetSelect();await saveWorkbookBytes(buf,f.name);$('workbookStatus').textContent=`✓ ${f.name} をJARVISに保存しました`;renderWorkbook()});
 $('sheetSelect').addEventListener('change',()=>{WB_SELECTED_COL=null;renderWorkbook()});
 $('workbookEditBtn').addEventListener('click',()=>{WB_EDIT=!WB_EDIT;$('workbookEditBtn').textContent=WB_EDIT?'✓ セル・項目名編集 OFF':'✎ セル・項目名編集 ON';renderWorkbook();$('workbookStatus').textContent=WB_EDIT?'編集モード：項目名（DR・業務名など）も直接書き換えできます。':'編集モードを終了しました。';});

 $('workbookAddColBtn')?.addEventListener('click',()=>{if(!WB)return;const x=workbookSheetData();if(!x)return;const max=Math.max(0,...x.a.map(r=>r.length));const pos=WB_SELECTED_COL==null?max:WB_SELECTED_COL+1;x.a.forEach((r,i)=>{while(r.length<pos)r.push('');r.splice(pos,0,i===2?'新しい項目':'')});WB_SELECTED_COL=pos;setWorkbookAOA(x.name,x.a);$('workbookStatus').textContent='＋ 列を追加しました。3行目の項目名を直接入力して保存してください。';});
 $('workbookDeleteColBtn')?.addEventListener('click',()=>{if(!WB||WB_SELECTED_COL==null){$('workbookStatus').textContent='削除したい列を先にタップしてください。';return}const x=workbookSheetData();x.a.forEach(r=>{if(r.length>WB_SELECTED_COL)r.splice(WB_SELECTED_COL,1)});WB_SELECTED_COL=Math.max(0,WB_SELECTED_COL-1);setWorkbookAOA(x.name,x.a);$('workbookStatus').textContent='－ 選択した列を削除しました。保存すると確定します。';});
 $('workbookMoveColLeftBtn')?.addEventListener('click',()=>{if(!WB||WB_SELECTED_COL==null||WB_SELECTED_COL<=0){$('workbookStatus').textContent='左へ移動する列を選択してください。';return}const x=workbookSheetData(),c=WB_SELECTED_COL;x.a.forEach(r=>{while(r.length<=c)r.push('');[r[c-1],r[c]]=[r[c],r[c-1]]});WB_SELECTED_COL=c-1;setWorkbookAOA(x.name,x.a);$('workbookStatus').textContent='← 列を左へ移動しました。';});
 $('workbookMoveColRightBtn')?.addEventListener('click',()=>{if(!WB||WB_SELECTED_COL==null){$('workbookStatus').textContent='右へ移動する列を選択してください。';return}const x=workbookSheetData(),c=WB_SELECTED_COL;x.a.forEach(r=>{while(r.length<=c+1)r.push('');[r[c],r[c+1]]=[r[c+1],r[c]]});WB_SELECTED_COL=c+1;setWorkbookAOA(x.name,x.a);$('workbookStatus').textContent='列を右へ移動しました →';});
 $('workbookAddRowBtn')?.addEventListener('click',()=>{if(!WB)return;const name=$('sheetSelect').value||WB.SheetNames[0],a=XLSX.utils.sheet_to_json(WB.Sheets[name],{header:1,defval:''});a.push(['','','',0,'',0,'',1,'']);WB.Sheets[name]=XLSX.utils.aoa_to_sheet(a);WB_EDIT=true;$('workbookEditBtn').textContent='✓ セル編集 OFF';renderWorkbook();$('workbookStatus').textContent='＋ 新しい入力行を追加しました。入力後「JARVISに保存」を押してください。'});
 $('workbookSaveBtn').addEventListener('click',async()=>{if(!WB)return;$('workbookStatus').textContent='保存するExcelがありません';const buf=XLSX.write(WB,{bookType:'xlsx',type:'array'});await saveWorkbookBytes(buf,WB_NAME);$('workbookStatus').textContent=`✓ 編集内容をJARVISに保存：${new Date().toLocaleTimeString('ja-JP')}`});
 $('workbookDownloadBtn').addEventListener('click',()=>{if(!WB)return;$('workbookStatus').textContent='ダウンロードするExcelがありません';XLSX.writeFile(WB,WB_NAME.replace(/\.xlsx?$/i,'')+'_JARVIS編集版.xlsx');$('workbookStatus').textContent='⬇ 編集可能なExcelをダウンロードしました'});
}
function setupSheetSelect(){if(!WB)return;$('sheetSelect').innerHTML=WB.SheetNames.map(n=>`<option>${esc(n)}</option>`).join('');}

async function load(){
  // V4.9.1: 公式の売上・単価データは毎回JSONから読み、古いlocalStorageの空データで上書きされないようにする。
  const r=await fetch('./jarvis-v4-data.json?ts='+Date.now(),{cache:'no-store'});
  if(!r.ok)throw new Error('jarvis-v4-data.json load failed: '+r.status);
  DATA=await r.json();
  const a=localStorage.getItem(ATT_KEY);
  ATT=cleanAttendance(a?JSON.parse(a):legacyAttendance());
  localStorage.setItem(ATT_KEY,JSON.stringify(ATT));
  populateForm();
  seedAugustShift();
  syncTodayFromAttendance();
  DATA.version='4.9.3';
  DATA.shift_version='2026-08-28-v493-stable-direct-edit';
  DATA.actuals_version='2026-08-28-v493-stable-sales-shift-delivery-edit';
  localStorage.setItem(STORAGE_KEY,JSON.stringify(DATA));
  initShiftControls();
  render();
  renderDrivers();
  renderShiftMatrix();
  try{ await initWorkbook(); }catch(e){ console.warn('Workbook init skipped:',e); const ws=document.getElementById('workbookStatus'); if(ws)ws.textContent='配送管理表は画面起動後に利用できます'; }
}
load().catch(e=>{console.error(e);const el=document.getElementById('pageSub');if(el)el.textContent='DATA LINK ERROR: '+e.message});
if('serviceWorker'in navigator){navigator.serviceWorker.getRegistrations().then(rs=>rs.forEach(r=>r.unregister())).catch(()=>{});} if('caches'in window){caches.keys().then(ks=>Promise.all(ks.map(k=>caches.delete(k)))).catch(()=>{});}


// V4.8.0 AI page bridge
(function(){
  const q=id=>document.getElementById(id);
  function aiSay(text,who='user'){
    const log=q('aiChatLog'); if(!log)return;
    const d=document.createElement('div'); d.className='msg '+(who==='jarvis'?'jarvis':'user');
    d.innerHTML=who==='jarvis'?'<b>JARVIS</b><p></p>':'<p></p>'; d.querySelector('p').textContent=text; log.appendChild(d); log.scrollTop=log.scrollHeight;
  }
  function sendAI(){
    const inp=q('aiChatText'); const text=inp?.value.trim(); if(!text)return; aiSay(text); inp.value='';
    const main=q('voiceText'),btn=q('voiceSend');
    if(main&&btn){main.value=text;btn.click();setTimeout(()=>{const msgs=document.querySelectorAll('#chatLog .msg.jarvis p');aiSay(msgs.length?msgs[msgs.length-1].textContent:'業務データを確認しました。','jarvis')},80)}
    else aiSay('現在のJARVIS内データで確認できる範囲から回答します。','jarvis');
  }
  q('aiChatSend')?.addEventListener('click',sendAI); q('aiChatText')?.addEventListener('keydown',e=>{if(e.key==='Enter')sendAI()});
  q('aiVoiceBtn')?.addEventListener('click',()=>q('voiceBtn')?.click());
})();


/* V4.8.3 ChatGPT-style JARVIS conversation bridge */
(()=>{
 const q=id=>document.getElementById(id), log=q('aiChatLog'), input=q('aiChatText');
 if(!log||!input)return;
 function row(role,text){const d=document.createElement('div');d.className='ai-row '+role;d.innerHTML=`<div class="ai-avatar">${role==='jarvis'?'J':'YOU'}</div><div class="ai-bubble"><b>${role==='jarvis'?'JARVIS':'YOU'}</b><p>${esc(text)}</p></div>`;log.appendChild(d);log.scrollTop=log.scrollHeight}
 function ask(text){text=(text||'').trim();if(!text)return;input.value='';row('user',text);const main=q('voiceText'),btn=q('voiceSend');if(main&&btn){const before=document.querySelectorAll('#chatLog .msg.jarvis p').length;main.value=text;btn.click();setTimeout(()=>{const msgs=document.querySelectorAll('#chatLog .msg.jarvis p');row('jarvis',msgs.length>before?msgs[msgs.length-1].textContent:'業務データを確認しました。')},90)}}
 q('aiChatSend')?.addEventListener('click',()=>ask(input.value));input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();ask(input.value)}});document.querySelectorAll('[data-aicmd]').forEach(b=>b.addEventListener('click',()=>ask(b.dataset.aicmd)));
 const SR2=window.SpeechRecognition||window.webkitSpeechRecognition; if(SR2){const rec=new SR2();rec.lang='ja-JP';rec.interimResults=false;rec.onstart=()=>{q('aiVoiceBtn')?.classList.add('listening');q('aiVoiceInline')?.classList.add('listening');if(q('aiVoiceStatus'))q('aiVoiceStatus').textContent='JARVIS LISTENING...'};rec.onend=()=>{q('aiVoiceBtn')?.classList.remove('listening');q('aiVoiceInline')?.classList.remove('listening');if(q('aiVoiceStatus'))q('aiVoiceStatus').textContent='音声入力 READY'};rec.onresult=e=>ask(e.results[0][0].transcript);rec.onerror=()=>row('jarvis','音声認識を開始できませんでした。マイクの許可を確認してください。');const start=()=>{try{rec.start()}catch{}};q('aiVoiceBtn')?.addEventListener('click',start);q('aiVoiceInline')?.addEventListener('click',start)}
})();

/* V4.8.8 REPORT / CONTACT / ABSENCE SUPPORT CORE */
(()=>{
 const REPORT_KEY='jarvis-v488-report-log';
 const canon=s=>String(s||'').replace(/[\s　]/g,'');
 const reportLog=()=>{try{return JSON.parse(localStorage.getItem(REPORT_KEY)||'[]')}catch{return[]}};
 const saveReport=(type,text)=>{const a=reportLog();a.unshift({time:new Date().toISOString(),type,text});localStorage.setItem(REPORT_KEY,JSON.stringify(a.slice(0,100)));renderReportLog()};
 function renderReportLog(){const el=document.getElementById('jarvisReportLog');if(!el)return;const a=reportLog().slice(0,5);el.innerHTML=a.length?'<b>RECENT REPORTS / 連絡記録</b>'+a.map(x=>`<div><span>${esc(x.type)}</span><small>${new Date(x.time).toLocaleString('ja-JP')}</small><p>${esc(x.text)}</p></div>`).join(''):''}
 function targetDate(text){const m=String(text).match(/(\d{1,2})[\/月](\d{1,2})日?/);return m?`2026-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`:today()}
 function targetArea(text){return Object.keys(AREA_PROJECTS).find(a=>String(text).includes(a))||''}
 function candidates(area,date){
   const by={}; ATT.filter(x=>x.date===date).forEach(x=>{const k=canon(x.driver);(by[k]??=[]).push(x)});
   const activeNames=new Set(DRIVERS.map(d=>canon(d.name)));
   const list=[];
   for(const [k,recs] of Object.entries(by)){
     if(!activeNames.has(k))continue;
     const working=recs.some(r=>r.status==='出勤'||r.status==='研修');
     const off=recs.some(r=>r.status==='休み');
     if(working||!off)continue;
     const d=DRIVERS.find(x=>canon(x.name)===k); if(!d)continue;
     const areas=Array.isArray(d.areas)?d.areas:[d.area].filter(Boolean);
     const same=areas.includes(area);
     list.push({name:d.name,areas,same,reason:same?`${area}経験あり・当日休み`:`${areas.join(' / ')}・当日休み`});
   }
   return list.sort((a,b)=>Number(b.same)-Number(a.same)||a.name.localeCompare(b.name,'ja'));
 }
 const oldExecute=execute;
 execute=function(raw){
   const text=(raw||'').trim(); if(!text)return;
   const t=text.replace(/\s/g,''), area=targetArea(text), date=targetDate(text);
   if(/欠車/.test(t)&&/(誰|対応|行け|候補|代走)/.test(t)){
     document.getElementById('voiceText').value='';addChat('user',text);
     const c=candidates(area,date); let r='';
     if(!area) r='欠車が出たエリア名も教えてください。例：「三島で欠車。誰が対応できる？」';
     else if(!c.length) r=`${date.slice(5).replace('-','/')} ${area}は、シフト上「休み」で確認できる対応候補が見つかりません。別拠点の状況確認が必要です。`;
     else r=`${area}の欠車対応候補です。${c.slice(0,5).map((x,i)=>`${i+1}番 ${x.name}（${x.reason}）`).join('。')}。実際に対応可能かは本人確認してください。`;
     saveReport('欠車相談',text);addChat('jarvis',r);speak(r);return;
   }
   if(/報告|連絡|共有|記録/.test(t)&&!/(開|見)/.test(t)){
     document.getElementById('voiceText').value='';addChat('user',text);
     if(/したい$|したいです$/.test(t)){const r='そのまま内容を送ってください。例：「三島 島田さん 本日休み」「静岡 配送完了」「荷主から時間変更の連絡」';addChat('jarvis',r);speak(r);return}
     const type=/事故|トラブル/.test(t)?'トラブル':/欠車|休み|欠勤|遅刻/.test(t)?'稼働連絡':/配送|完了/.test(t)?'配送報告':'連絡';
     saveReport(type,text);const r=`${type}として記録しました。管理表を変更する内容の場合は「シフトも変更して」と続けて指示してください。`;addChat('jarvis',r);speak(r);return;
   }
   return oldExecute(raw);
 };
 renderReportLog();
 document.querySelector('.command-core-v487')?.addEventListener('click',()=>go('ai'));
 document.querySelector('.command-core-v487')?.setAttribute('role','button');
 document.querySelector('.command-core-v487')?.setAttribute('aria-label','JARVISチャットを開く');
})();
